import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

function StudentCourses() {
  const navigate = useNavigate();
  const [cours, setCours] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) {
      navigate('/login');
      return;
    }
    fetchCours();
  }, [navigate]);

  const fetchCours = async () => {
    try {
      setLoading(true);
      const response = await api.get('/api/student/courses');
      setCours(response.data.courses || []);
    } catch (error) {
      console.error('Erreur chargement cours:', error);
      setError('Erreur lors du chargement des cours');
    } finally {
      setLoading(false);
    }
  };

  const handleDownload = async (coursId, fileName) => {
    try {
      const response = await api.get(`/api/student/courses/${coursId}/file`, {
        responseType: 'blob'
      });
      
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', fileName);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Erreur téléchargement:', error);
      alert('Erreur lors du téléchargement du fichier');
    }
  };

  // FONCTION AJOUTÉE POUR VOIR LES DÉTAILS
  const handleViewDetails = (cours) => {
    // Vous pouvez naviguer vers une page de détails ou afficher un modal
    console.log('Détails du cours:', cours);
    
    // Option 1: Naviguer vers une page de détails
    // navigate(`/course-details/${cours.id}`);
    
    // Option 2: Afficher les détails dans une alerte (temporaire)
    alert(`Détails du cours:\n\nTitre: ${cours.title}\nDescription: ${cours.description || 'Aucune description'}\nProfesseur: ${cours.professeur_nom}\nClasse: ${cours.class_name}\nNiveau: ${cours.level}\nDate: ${new Date(cours.date_creation).toLocaleDateString('fr-FR')}`);
  };

  const handleBack = () => {
    navigate('/dashboard-student');
  };

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <div style={styles.spinner}></div>
        <p>Chargement de vos cours...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <button onClick={handleBack} style={styles.backButton}>
          ← Retour au Dashboard
        </button>
        <h1 style={styles.title}>Mes Cours</h1>
        <div style={styles.headerActions}>
          <span style={styles.counter}>
            {cours.length} cours disponible{cours.length > 1 ? 's' : ''}
          </span>
        </div>
      </header><br></br><br></br><br></br>

      <main style={styles.main}>
        {error && (
          <div style={styles.errorAlert}>
            {error}
          </div>
        )}

        {cours.length === 0 ? (
          <div style={styles.emptyState}>
            <div style={styles.emptyIcon}>📚</div>
            <h3>Aucun cours disponible</h3>
            <p>Vos cours apparaîtront ici une fois assignés par vos professeurs.</p>
          </div>
        ) : (
          <div style={styles.coursesGrid}>
            {cours.map((cour) => (
              <div key={cour.id} style={styles.courseCard}>
                <div style={styles.courseHeader}>
                  <h3 style={styles.courseTitle}>{cour.title}</h3>
                  <span style={styles.courseLevel}>{cour.level}</span>
                </div>
                
                <div style={styles.courseInfo}>
                  <p style={styles.courseDescription}>
                    {cour.description || 'Aucune description disponible'}
                  </p>
                  
                  <div style={styles.courseMeta}>
                    <div style={styles.metaItem}>
                      <strong>Classe:</strong> {cour.class_name}
                    </div>
                    <div style={styles.metaItem}>
                      <strong>Professeur:</strong> {cour.professeur_nom}
                    </div>
                    <div style={styles.metaItem}>
                      <strong>Date:</strong> {new Date(cour.date_creation).toLocaleDateString('fr-FR')}
                    </div>
                  </div>
                </div>

                <div style={styles.courseActions}>
                  {cour.fichier && (
                    <button
                      onClick={() => handleDownload(cour.id, cour.fichier)}
                      style={styles.downloadButton}
                    >
                      📥 Télécharger le cours
                    </button>
                  )}
                  {/* BOUTON CORRIGÉ */}
                  <button 
                    onClick={() => handleViewDetails(cour)}
                    style={styles.viewButton}
                  >
                    👁️ Voir les détails
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
}

const styles = {
  container: {
    minHeight: '100vh',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
  },
  header: {
    background: 'rgba(255, 255, 255, 0.95)',
    backdropFilter: 'blur(10px)',
    padding: '1.5rem 2rem',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    boxShadow: '0 4px 20px rgba(0, 0, 0, 0.1)',
  },
  backButton: {
    padding: '0.5rem 1rem',
    background: 'transparent',
    border: '2px solid #667eea',
    color: '#667eea',
    borderRadius: '8px',
    cursor: 'pointer',
    fontWeight: '600',
  },
  title: {
    color: '#2d3748',
    fontSize: '1.8rem',
    fontWeight: '700',
    margin: 0,
  },
  headerActions: {
    display: 'flex',
    alignItems: 'center',
    gap: '1rem',
  },
  counter: {
    background: '#667eea',
    color: 'white',
    padding: '0.5rem 1rem',
    borderRadius: '20px',
    fontSize: '0.9rem',
    fontWeight: '600',
  },
  main: {
    maxWidth: '1200px',
    margin: '0 auto',
    padding: '2rem',
  },
  errorAlert: {
    background: '#fed7d7',
    color: '#c53030',
    padding: '1rem',
    borderRadius: '8px',
    marginBottom: '2rem',
    border: '1px solid #feb2b2',
  },
  emptyState: {
    background: 'white',
    borderRadius: '16px',
    padding: '3rem',
    textAlign: 'center',
    boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)',
  },
  emptyIcon: {
    fontSize: '4rem',
    marginBottom: '1rem',
  },
  coursesGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fill, minmax(350px, 1fr))',
    gap: '1.5rem',
  },
  courseCard: {
    background: 'white',
    borderRadius: '16px',
    padding: '1.5rem',
    boxShadow: '0 4px 20px rgba(0, 0, 0, 0.08)',
    border: '1px solid rgba(255, 255, 255, 0.2)',
    display: 'flex',
    flexDirection: 'column',
    height: '100%',
  },
  courseHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    marginBottom: '1rem',
  },
  courseTitle: {
    color: '#2d3748',
    fontSize: '1.2rem',
    fontWeight: '600',
    margin: 0,
    flex: 1,
  },
  courseLevel: {
    background: '#e2e8f0',
    color: '#4a5568',
    padding: '0.25rem 0.75rem',
    borderRadius: '12px',
    fontSize: '0.8rem',
    fontWeight: '600',
    marginLeft: '1rem',
  },
  courseDescription: {
    color: '#718096',
    lineHeight: 1.5,
    marginBottom: '1rem',
    flex: 1,
  },
  courseMeta: {
    background: '#f8fafc',
    padding: '1rem',
    borderRadius: '8px',
    marginBottom: '1rem',
  },
  metaItem: {
    marginBottom: '0.5rem',
    fontSize: '0.9rem',
    color: '#4a5568',
  },
  courseActions: {
    display: 'flex',
    gap: '0.5rem',
    flexWrap: 'wrap',
  },
  downloadButton: {
    padding: '0.5rem 1rem',
    background: '#48bb78',
    color: 'white',
    border: 'none',
    borderRadius: '6px',
